def calculate_total(items):
    t = sum(i.price for i in items)
    if items and items[0].coupon:
        t -= items[0].coupon.amount
    return t

def calculate_total_with_tax(items, tax):
    t = sum(i.price for i in items)
    return round(t * (1 + tax), 2)

def format_receipt(total):
